  function show(el,ev){
    var raw=el.getAttribute('data-attrs');
    if(!raw) return;
    try{var d=JSON.parse(raw)}catch(e){return}
    var h='';
    for(var k in d){
      var v=d[k];
      if(Array.isArray(v)) v=v.join(', ');
      h+='<div><b>'+k+'</b>: '+v+'</div>';
    }
    if(!h) return;
    tip.innerHTML=h;tip.style.display='block';
    place(ev);
